use digimon_dsl::{compile::compile,pack::CardPack,spec::CardSpec};
fn card(process:&str)->CardSpec{serde_yml::from_str(&format!("card: TEST-SUSPEND-ALL\nname: Test\nkind: digimon\ncolor: [blue]\nlevel: 3\ncost: 3\ndp: 2000\neffects:\n - kind: replacement\n   trigger: when_would_leave_battle_area\n   optional: true\n   process:\n{process}")).unwrap()}
#[test]fn typed_suspend_plural_compiles_and_pack_roundtrips(){let c=compile(&card("    - suspend_and_cancel_all_matching_leaves: {target: source, filter: {kind: digimon}}" )).unwrap();let p=CardPack::new("suspend-all",vec![c]);assert_eq!(CardPack::from_bytes(&p.to_bytes().unwrap()).unwrap(),p);}
#[test]fn distinct_plural_subject_filters_in_one_clause_are_rejected(){let e=compile(&card("    - suspend_and_cancel_all_matching_leaves: {target: source, filter: {kind: digimon}}\n    - suspend_and_cancel_all_matching_leaves: {target: source, filter: {kind: tamer}}" )).unwrap_err();assert!(e.iter().any(|e|e.message.contains("one plural prevention subject filter")));}
#[test]fn subject_filter_binding_is_validated(){let c=card("    - suspend_and_cancel_all_matching_leaves: {target: source, filter: {binding_exists: missing}}");assert!(digimon_dsl::validator::validate(&c,&digimon_dsl::validator::ValidationContext{raw_rust:&digimon_dsl::raw_rust_registry::StubRegistry::empty()}).is_err());}
